function f(t){if(t==null||Number.isNaN(t))return"-";const r=Math.abs(t);return r>=1e9?(t/1e9).toFixed(1).replace(/\.0$/,"")+"B":r>=1e6?(t/1e6).toFixed(1).replace(/\.0$/,"")+"M":r>=1e3?(t/1e3).toFixed(1).replace(/\.0$/,"")+"K":new Intl.NumberFormat().format(t)}function m(t){if(t==null||Number.isNaN(t))return"-";const r=Math.floor(t/3600),o=Math.floor(t%3600/60),i=Math.floor(t%60),n=String(o).padStart(2,"0"),e=String(i).padStart(2,"0");return r>0?`${r}:${n}:${e}`:`${o}:${e}`}function u(t){if(!t)return"-";const r=new Date(t);return Number.isNaN(r.getTime())?t:r.toLocaleDateString(void 0,{year:"numeric",month:"short",day:"numeric"})}function c(t){if(!t)return"-";const r=new Date(t);return Number.isNaN(r.getTime())?t:r.toLocaleString(void 0,{year:"numeric",month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}function s(t){if(!t)return"-";const r=new Date(t);if(Number.isNaN(r.getTime()))return t;const o=Date.now()-r.getTime(),i=Math.floor(o/1e3);if(i<60)return"just now";const n=Math.floor(i/60);if(n<60)return`${n}m ago`;const e=Math.floor(n/60);if(e<24)return`${e}h ago`;const a=Math.floor(e/24);return a<30?`${a}d ago`:u(t)}function N(t){return t==null||Number.isNaN(t)?"-":`${(t*100).toFixed(1)}%`}function d(t){return t==null||Number.isNaN(t)?"-":new Intl.NumberFormat(void 0,{style:"currency",currency:"USD",maximumFractionDigits:0}).format(t)}export{d as a,c as b,N as c,m as d,u as e,f,s as t};
